#!/usr/bin/env python3
from __future__ import annotations

import base64
import re
import shutil
import subprocess
import sys
import time
from pathlib import Path

PATCH_ID = "MEMEFLOW_DISCOVERY_NATIVE_PLATFORM_V3"
OLD_V2 = "MEMEFLOW_DISCOVERY_PLATFORM_DROPDOWN_V2"
STAMP = time.strftime("%Y%m%d-%H%M%S")
RUNTIME = base64.b64decode("").decode("utf-8")

def log(msg):
    print("[DISCOVERY-NATIVE-V3] " + str(msg), flush=True)

def find_root():
    candidates = [
        Path.cwd(),
        Path.cwd() / "memeflow-app",
        Path.home() / "workspace",
        Path.home() / "workspace" / "memeflow-app",
        Path("/home/runner/workspace"),
        Path("/home/runner/workspace/memeflow-app"),
    ]
    for root in candidates:
        try:
            root = root.resolve()
        except Exception:
            continue
        if (root / "system.js").is_file() and (root / "app-server.mjs").is_file():
            return root

    for base in [Path("/home/runner/workspace"), Path.cwd()]:
        if not base.exists():
            continue
        for p in base.glob("**/system.js"):
            if (p.parent / "app-server.mjs").is_file():
                return p.parent.resolve()

    raise RuntimeError("MEMEFLOW system.js/app-server.mjs root not found")

ROOT = find_root()
SYSTEM = ROOT / "system.js"
SERVER = ROOT / "app-server.mjs"
BACKUP = ROOT / (".discovery-native-v3-backup-" + STAMP)
BACKUP.mkdir(parents=True, exist_ok=True)
changed = []

def rel(path):
    return path.resolve().relative_to(ROOT.resolve())

def backup(path):
    if path in changed:
        return
    dst = BACKUP / rel(path)
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(path, dst)
    changed.append(path)

def write(path, data):
    backup(path)
    path.write_text(data, encoding="utf-8")
    log("patched " + str(rel(path)))

def rollback(reason):
    log("ERROR: " + str(reason))
    for path in reversed(changed):
        src = BACKUP / rel(path)
        if src.exists():
            shutil.copy2(src, path)
            log("restored " + str(rel(path)))
    log("ROLLBACK COMPLETE")
    sys.exit(1)

def remove_old_v2_if_safe(text):
    marker = "// " + OLD_V2
    start = text.find(marker)
    if start < 0:
        return text, False

    tail = text[start:]

    # V2 was installed as an appended final IIFE. Remove it only when it is
    # demonstrably the final patch region; otherwise leave it and V3 neutralizes
    # its DOM/CSS at runtime instead of risking project code.
    if "window.__mfDiscoveryPlatformDropdownV2" not in tail:
        return text, False

    end = tail.rfind("})();")
    if end < 0:
        return text, False

    suffix = tail[end + len("})();"):]

    if suffix.strip():
        return text, False

    return text[:start].rstrip() + "\n", True

try:
    log("root: " + str(ROOT))

    server = SERVER.read_text(encoding="utf-8")
    if "/api/discovery-source" not in server:
        raise RuntimeError(
            "Discovery Router V1.1 is not present: /api/discovery-source missing"
        )

    text = SYSTEM.read_text(encoding="utf-8")

    if PATCH_ID in text:
        log("V3 already installed")
        sys.exit(0)

    text, removed = remove_old_v2_if_safe(text)

    if removed:
        log("removed old custom V2 dropdown completely")
    else:
        log("V2 source was not safely removable; V3 will neutralize it in DOM")

    text = (
        text.rstrip()
        + "\n\n// " + PATCH_ID + "\n"
        + RUNTIME
        + "\n"
    )

    write(SYSTEM, text)

    check = subprocess.run(
        ["node", "--check", str(SYSTEM)],
        cwd=ROOT,
        capture_output=True,
        text=True
    )

    if check.returncode != 0:
        raise RuntimeError(
            "node --check system.js failed:\n"
            + (check.stderr or check.stdout)
        )

    final = SYSTEM.read_text(encoding="utf-8")

    for token in [
        PATCH_ID,
        "mfdn-native-platform-v3",
        "<select",
        "/api/discovery-source",
        "Pump.fun",
        "Hybrid",
        "mfdn-dex-off-v3"
    ]:
        # `<select` exists only in DOM at runtime, so validate createElement instead.
        if token == "<select":
            token = "createElement('select')"
        if token not in final:
            raise RuntimeError("validation missing: " + token)

    log("system.js syntax OK")
    log("INSTALL COMPLETE")
    log("PLATFORM now uses a native HTML select like the other iOS settings")
    log("iPhone/Safari will show its native system picker")
    log("options: Pump.fun / DEX / Hybrid")
    log("old custom V2 dropdown is removed or neutralized")
    log("DEX-only compatibility dimming is preserved")
    log("HYBRID compatibility notes are preserved")
    log("backup: " + str(BACKUP))
    log("Hard-refresh System settings.")

except Exception as exc:
    rollback(exc)
